local function wantRaritySet()
    local sel = selSet("pe_rarities"); if not sel then return nil end
    local names = {}
    for disp in pairs(sel) do names[RARITY_NAME[disp] or disp] = true end
    return names
end
local function matches(m)
    if type(m:GetAttribute("timer")) ~= "number" then return false end
    local wantRar = wantRaritySet()
    if wantRar then
        local rar = friendRarity(m)
        if not (rar and wantRar[rar]) then return false end
    end
    local wantMut = selSet("pe_mutations")
    if wantMut then
        local mut = friendMutation(m)
        if not (mut and wantMut[mut]) then return false end
    end
    return true
end
local function matchingLoose()
    local h = hrp(); local myPos = h and h.Position
    local range = (Opt.pe_range and Opt.pe_range.Value) or 700
    local out = {}
    for _, m in ipairs(scanLooseFriends()) do
        if matches(m) then
            local p = pivotPos(m)
            local d = (p and myPos) and (p - myPos).Magnitude or math.huge
            if d <= range then out[#out + 1] = { m = m, d = d } end
        end
    end
    table.sort(out, function(a, b) return a.d < b.d end)
    local list = {}
    for _, e in ipairs(out) do list[#list + 1] = e.m end
    return list
end
local function pickParkPart()
    local wantRar = wantRaritySet()
    local parts = allRarityTexts()
    if wantRar then for _, rt in ipairs(parts) do if wantRar[rt.name] then return rt.part end end end
    return parts[1] and parts[1].part
end
local PARK_TOL = 6
local PARK_DWELL = 1.0
local function onParkSpot(park)
    local h = hrp(); if not h or not park then return false end
    local d = (Vector3.new(park.Position.X, 0, park.Position.Z) - Vector3.new(h.Position.X, 0, h.Position.Z)).Magnitude
