            local d0 = os.clock()
            local stable = true
            while os.clock() - d0 < PARK_DWELL do
                if (keepGoing and not keepGoing()) or not isCarrying() then stable = false break end
                if not onParkSpot(park) then tpTo(park.Position, 3) end
