local antiLagConn
local function applyAntiLagOne(o)
    if o:IsA("ParticleEmitter") or o:IsA("Trail") or o:IsA("Beam") then pcall(function() o.Enabled = false end)
    elseif o:IsA("Smoke") or o:IsA("Fire") or o:IsA("Sparkles") then pcall(function() o:Destroy() end)
    elseif o:IsA("PointLight") or o:IsA("SpotLight") or o:IsA("SurfaceLight") then pcall(function() o.Enabled = false end)
    elseif o:IsA("Decal") or o:IsA("Texture") then pcall(function() o.Transparency = 1 end)
    elseif o:IsA("BasePart") then
        pcall(function() o.Material = Enum.Material.SmoothPlastic end)
        pcall(function() o.Reflectance = 0 end)
        pcall(function() o.CastShadow = false end)
    end
end
local function stripFriendAnimations()
    local live = Workspace:FindFirstChild("Live"); if not live then return end
    for _, folder in ipairs({ live:FindFirstChild("PlayerFriends"), live:FindFirstChild("Friends") }) do
        if folder then
            for _, d in ipairs(folder:GetDescendants()) do
                if d:IsA("Animator") then for _, tr in ipairs(d:GetPlayingAnimationTracks()) do pcall(function() tr:Stop() end) end end
            end
        end
    end
end
function setAntiLag(state)
    if antiLagConn then antiLagConn:Disconnect(); antiLagConn = nil end
    if not state then return end
    pcall(function() Lighting.GlobalShadows = false end)
    pcall(function() Lighting.FogEnd = 9e9; Lighting.FogStart = 9e9 end)
    pcall(function() settings().Rendering.QualityLevel = 1 end)
    pcall(function() settings().Rendering.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level04 end)
    for _, e in ipairs(Lighting:GetDescendants()) do if e:IsA("PostEffect") or e:IsA("Atmosphere") or e:IsA("Clouds") then pcall(function() e.Enabled = false end) end end
    pcall(function() Workspace.Clouds.Enabled = false end)
    pcall(function() local t = Workspace.Terrain; t.WaterWaveSize = 0; t.WaterWaveSpeed = 0; t.WaterReflectance = 0; t.WaterTransparency = 1; t.Decoration = false end)
    antiLagConn = Workspace.DescendantAdded:Connect(function(o) if RUNNING and on("pe_antilag") then applyAntiLagOne(o) end end)
    onClean(function() if antiLagConn then pcall(function() antiLagConn:Disconnect() end) end end)
    task.spawn(function()
        local n = 0
        for _, o in ipairs(Workspace:GetDescendants()) do
            if not on("pe_antilag") then break end
            applyAntiLagOne(o); n = n + 1; if n % 500 == 0 then RunService.Heartbeat:Wait() end
        end
        stripFriendAnimations()
    end)
    task.spawn(function() while RUNNING and on("pe_antilag") do stripFriendAnimations(); task.wait(4) end end)
end
